using UnityEngine;using Codice.Multiplayer;using System;using System.Reflection;
public static class PingProtocolProbe{const BindingFlags F=BindingFlags.Instance|BindingFlags.NonPublic;public static string Run(){if(LanSession.Active)return "Skipped: real network active";var go=new GameObject("Ping protocol probe");var session=go.AddComponent<LanSession>();try{var type=typeof(LanSession);var pt=type.GetNestedType("Peer",BindingFlags.NonPublic);var peer=Activator.CreateInstance(pt,true);string response=null;pt.GetField("accepted").SetValue(peer,true);pt.GetField("wire").SetValue(peer,new LanWire(s=>response=s));type.GetMethod("Handle",F).Invoke(session,new[]{peer,(object)new LanMessage{type="ping",elapsed=123.5f}});var pong=JsonUtility.FromJson<LanMessage>(response);if(pong.type!="pong"||pong.elapsed!=123.5f)throw new Exception("Echo failed");float sent=Time.realtimeSinceStartup-.08f;type.GetField("client",F).SetValue(session,true);type.GetField("pingSent",F).SetValue(session,sent);type.GetField("lastServer",F).SetValue(session,Time.realtimeSinceStartup);type.GetField("heartbeat",F).SetValue(session,Time.realtimeSinceStartup+100);var wire=new LanWire(s=>{});type.GetField("server",F).SetValue(session,wire);wire.Receive(JsonUtility.ToJson(new LanMessage{type="pong",elapsed=sent}));type.GetMethod("Update",F).Invoke(session,null);float rtt=session.PingMilliseconds;if(rtt<75||rtt>150)throw new Exception("Unexpected RTT "+rtt);type.GetField("pingReceived",F).SetValue(session,Time.realtimeSinceStartup-6);if(session.PingMilliseconds!=-1)throw new Exception("Stale ping retained");return "PASS echo, RTT="+rtt+"ms, stale timeout";}finally{UnityEngine.Object.DestroyImmediate(go);}}}
